mapper.select:
SELECT qr.quiz_room_id AS quizRoomId, qr.room_title AS roomTitle, qr.joined_count AS joinedCount, qr.room_capacity AS roomCapacity, qr.room_status AS roomStatus, qr.is_private AS isPrivate,
c.category_id AS categoryId, c.category_name AS categoryName
FROM tb_quiz_room qr JOIN tb_category c ON qr.category_id = c.category_id WHERE qr.is_private = 'N' AND qr.room_status = 'W' ORDER BY qr.quiz_room_id DESC LIMIT #{limit} OFFSET #{offset}
